import { sendToastMessage } from "@/functions/messages/toastMessage";

export function fmtCompact(v: number): string {
    if (!Number.isFinite(v)) return 'R$ 0';
    const abs = Math.abs(v);
    const sign = v < 0 ? '-' : '';
    if (abs >= 1_000_000)
        return `${sign}R$ ${(abs / 1_000_000).toLocaleString('pt-BR', { minimumFractionDigits: 1, maximumFractionDigits: 1 })}M`;
    if (abs >= 1_000)
        return `${sign}R$ ${(abs / 1_000).toLocaleString('pt-BR', { minimumFractionDigits: 1, maximumFractionDigits: 1 })}k`;
    return v.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL', minimumFractionDigits: 2, maximumFractionDigits: 2 });
}
import { addYears, differenceInDays, differenceInMonths, differenceInYears, parseISO } from 'date-fns';
import { TagVariant } from "../types";

export function formatDate(dateString: string): string {
    const date = new Date(dateString);
    const months = [
        'JAN',
        'FEV',
        'MAR',
        'ABR',
        'MAI',
        'JUN',
        'JUL',
        'AGO',
        'SET',
        'OUT',
        'NOV',
        'DEZ',
    ];
    return `${months[date.getUTCMonth()]}/${date.getUTCFullYear()}`;
}

/**
 * Formata a duração entre duas datas em uma string legível (anos e meses).
 * @param initialDate Data inicial no formato "YYYY-MM-DD".
 * @param finalDate Data final no formato "YYYY-MM-DD".
 * @returns String formatada (ex: "1 ano e 3 meses").
 */
export function formatDuration(initialDate: string, finalDate: string): string {
    if (!initialDate || !finalDate) return '-';

    const start = parseISO(initialDate);
    const end = parseISO(finalDate);

    const totalDays = differenceInDays(end, start);

    if (totalDays < 30) {
        return `${totalDays} dia${totalDays !== 1 ? 's' : ''}`;
    }

    const years = differenceInYears(end, start);
    const startAfterYears = addYears(start, years);
    const months = differenceInMonths(end, startAfterYears);

    if (years === 0) {
        return `${months} ${months === 1 ? 'mês' : 'meses'}`;
    }

    if (months === 0) {
        return `${years} ${years === 1 ? 'ano' : 'anos'}`;
    }

    return `${years} ${years === 1 ? 'ano' : 'anos'} e ${months} ${months === 1 ? 'mês' : 'meses'}`;
}

export function getEsferaVariant(esfera: string): TagVariant {
    switch (esfera) {
        case 'FEDERAL':
            return 'federal';
        case 'ESTADUAL':
            return 'estadual';
        case 'MUNICIPAL':
            return 'municipal';
        default:
            return 'federal';
    }
}

export function handleCopyInvestmentId(text: string) {
    navigator.clipboard.writeText(text);
    sendToastMessage({
        title: 'Copiado para área de transferência.',
        type: 'success',
    });
}

export function getEspecieVariant(especie: string): TagVariant {
    switch (especie) {
        case 'Principal':
            return 'principal';
        case 'Juros':
            return 'juros';
        case 'Honorários':
            return 'honorarios';
        default:
            return 'principal';
    }
}

export const getTagStyle = (variant: TagVariant) => {
    switch (variant) {
        case 'federal':
            return 'bg-emerald-500 text-white hover:bg-emerald-500';
        case 'estadual':
            return 'bg-blue-500 text-white hover:bg-blue-500';
        case 'municipal':
            return 'bg-purple-500 text-white hover:bg-purple-500';
        case 'tribunal':
            return 'bg-sky-100 text-sky-700 hover:bg-sky-100';
        case 'year':
            return 'bg-amber-100 text-amber-700 hover:bg-amber-100';
        case 'principal':
            return 'bg-emerald-100 text-emerald-700 hover:bg-emerald-100';
        case 'juros':
            return 'bg-orange-100 text-orange-700 hover:bg-orange-100';
        case 'honorarios':
            return 'bg-violet-100 text-violet-700 hover:bg-violet-100';
        default:
            return 'bg-muted text-muted-foreground';
    }
};

