1	import { tenantsInfo } from '@/constants/tenants-info';
2	import { formatCurrency } from '@/functions/formaters/formatCurrency';
3	import { formatDeducaoTipoLabel } from '@/functions/formaters/formatDeducaoTipoLabel';
4	import type { CVLDResultProps } from '@/interfaces/IResultCVLD';
5	import type { CvldFormInputsProps } from '@/types/cvldform';
6	import { getTenantFromUrl } from '@/utils/getHostFromUrl';
7	import jsPDF from 'jspdf';
8	
9	interface GeneratePDFCalculadoraParams {
10	    calcResults: CVLDResultProps;
11	    formData: Partial<CvldFormInputsProps>;
12	}
13	
14	const formatDate = (date: string | null | undefined): string => {
15	    if (!date) return '-';
16	    try {
17	        const d = new Date(date + 'T00:00:00');
18	        return isNaN(d.getTime()) ? '-' : d.toLocaleDateString('pt-BR');
19	    } catch {
20	        return '-';
21	    }
22	};
23	
24	const formatBoolean = (value: boolean | null | undefined): string => {
25	    if (value === null || value === undefined) return '-';
26	    return value ? 'Sim' : 'Não';
27	};
28	
29	const formatPercent = (value: number | string | null | undefined): string => {
30	    if (value === null || value === undefined) return '-';
31	    const num = typeof value === 'string' ? parseFloat(value) : value;
32	    return isNaN(num) ? '-' : `${(num * 100).toFixed(2)}%`;
33	};
34	
35	export async function generatePDFCalculadora({
36	    calcResults,
37	    formData,
38	}: GeneratePDFCalculadoraParams): Promise<void> {
39	    try {
40	        const tenant = getTenantFromUrl();
41	        const tenantInfo = tenantsInfo[tenant as keyof typeof tenantsInfo] || tenantsInfo.celer;
42	
43	        const pdf = new jsPDF('p', 'mm', 'a4');
44	        const pageWidth = pdf.internal.pageSize.getWidth();
45	        const pageHeight = pdf.internal.pageSize.getHeight();
46	        const margin = 20;
47	
48	        // Cabeçalho
49	        pdf.setFillColor(59, 130, 246);
50	        pdf.rect(0, 0, pageWidth, 35, 'F');
51	
