import { tenantsInfo } from '@/constants/tenants-info';
import { formatCurrency } from '@/functions/formaters/formatCurrency';
import { formatDeducaoTipoLabel } from '@/functions/formaters/formatDeducaoTipoLabel';
import type { CVLDResultProps } from '@/interfaces/IResultCVLD';
import type { CvldFormInputsProps } from '@/types/cvldform';
import { getTenantFromUrl } from '@/utils/getHostFromUrl';
import jsPDF from 'jspdf';

interface GeneratePDFCalculadoraParams {
    calcResults: CVLDResultProps;
    formData: Partial<CvldFormInputsProps>;
}

const formatDate = (date: string | null | undefined): string => {
    if (!date) return '-';
    try {
        const d = new Date(date + 'T00:00:00');
        return isNaN(d.getTime()) ? '-' : d.toLocaleDateString('pt-BR');
    } catch {
        return '-';
    }
};

const formatBoolean = (value: boolean | null | undefined): string => {
    if (value === null || value === undefined) return '-';
    return value ? 'Sim' : 'Não';
};

const formatPercent = (value: number | string | null | undefined): string => {
    if (value === null || value === undefined) return '-';
    const num = typeof value === 'string' ? parseFloat(value) : value;
    return isNaN(num) ? '-' : `${(num * 100).toFixed(2)}%`;
};

export async function generatePDFCalculadora({
    calcResults,
    formData,
}: GeneratePDFCalculadoraParams): Promise<void> {
    try {
        const tenant = getTenantFromUrl();
        const tenantInfo = tenantsInfo[tenant as keyof typeof tenantsInfo] || tenantsInfo.celer;

