            },
            {
                label: 'Valor Principal:',
                value: formData.valor_principal ? formatCurrency(formData.valor_principal) : '-',
            },
            {
                label: 'Valor Juros:',
                value: formData.valor_juros ? formatCurrency(formData.valor_juros) : '-',
